source='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    wall = next(v for v, _ in counts.most_common() if v != background)
    out = [row[:] for row in grid]
    for top in range(h - 1):
        for bottom in range(top + 2, h):
            for left in range(w - 1):
                for right in range(left + 2, w):
                    top_wall = all(grid[top][c] == wall for c in range(left, right + 1))
                    bottom_wall = all(grid[bottom][c] == wall for c in range(left, right + 1))
                    left_wall = all(grid[r][left] == wall for r in range(top, bottom + 1))
                    right_wall = all(grid[r][right] == wall for r in range(top, bottom + 1))
                    if (top != 0 and not top_wall) or (bottom != h-1 and not bottom_wall):
                        continue
                    if (left != 0 and not left_wall) or (right != w-1 and not right_wall):
                        continue
                    actual = (top_wall, bottom_wall, left_wall, right_wall)
                    if sum(actual) < 3:
                        continue
                    r0 = top + top_wall; r1 = bottom - bottom_wall
                    c0 = left + left_wall; c1 = right - right_wall
                    if r1 < r0 or c1 < c0 or (r1-r0+1) == (c1-c0+1):
                        continue
                    for r in range(r0, r1 + 1):
                        for c in range(c0, c1 + 1):
                            out[r][c] = 4
    return out
